package workerpool

import (
	"sort"
	"testing"
)

func TestWorkerPoolBasic(t *testing.T) {
	wp := New(3)
	wp.Start()
	for i := 1; i <= 9; i++ {
		n := i
		wp.Submit(func() int { return n * n })
	}
	results := wp.Stop()
	if len(results) != 9 {
		t.Fatalf("want 9 results got %d", len(results))
	}
}

func TestWorkerPoolSums(t *testing.T) {
	wp := New(2)
	wp.Start()
	for i := 1; i <= 5; i++ {
		n := i
		wp.Submit(func() int { return n })
	}
	results := wp.Stop()
	total := 0
	for _, r := range results {
		total += r
	}
	if total != 15 {
		t.Fatalf("want sum 15 got %d", total)
	}
}

func TestWorkerPoolOrdering(t *testing.T) {
	wp := New(1) // single worker preserves order
	wp.Start()
	for i := 0; i < 5; i++ {
		n := i
		wp.Submit(func() int { return n })
	}
	results := wp.Stop()
	sort.Ints(results)
	for i, v := range results {
		if v != i {
			t.Fatalf("want %d got %d", i, v)
		}
	}
}

func TestWorkerPoolEmpty(t *testing.T) {
	wp := New(2)
	wp.Start()
	results := wp.Stop()
	if len(results) != 0 {
		t.Fatalf("want 0 results got %d", len(results))
	}
}

func TestWorkerPoolSingleWorker(t *testing.T) {
	wp := New(1)
	wp.Start()
	wp.Submit(func() int { return 42 })
	results := wp.Stop()
	if len(results) != 1 || results[0] != 42 {
		t.Fatalf("want [42] got %v", results)
	}
}

